{/* Primary field trigger */}
<AceDropdownMenu
  triggerLabel="Dropdown Label"
  triggerMode="field"
  panelWidth="wide"
  items={[
    { type: 'item', label: 'Menu Item 1', onSelect },
    { type: 'item', label: 'Menu Item 2', onSelect },
  ]}
/>

{/* Secondary / FilterChip trigger — opens MenuList (sections + Select All + checkboxes) */}
